sctp_disposition_t sctp_process_oob_chunk(struct net *net, const struct sctp_endpoint *ep, const struct sctp_association *asoc, sctp_subtype_t type, void *arg, sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;

    /* Increment statistics for processing out-of-band chunks */
    net->stats[sctp_stats::SCTP_MIB_INCTRLCHUNKS].inc();

    /* Validate chunk length */
    if (chunk->chunk_length < sizeof(sctp_chunk_t)) {
        return SCTP_DISPOSITION_NOMEM;
    }

    switch (type) {
        case SCTP_SUBTYPE_SHUTDOWN_ACK:
            {
                sctp_shutdown_ack_chunk_t *shutdown_ack = (sctp_shutdown_ack_chunk_t *)chunk;
                sctp_cmd_seq_add(commands, sctp_cmd_shutdown_ack(shutdown_ack->advertising_side));
                return SCTP_DISPOSITION_CONSUME;
            }

        case SCTP_SUBTYPE_COOKIE_ACK:
            {
                sctp_cookie_ack_chunk_t *cookie_ack = (sctp_cookie_ack_chunk_t *)chunk;
                sctp_cmd_seq_add(commands, sctp_cmd_cookie_ack(cookie_ack->cookie));
                return SCTP_DISPOSITION_CONSUME;
            }

        case SCTP_SUBTYPE_ERROR:
            {
                sctp_error_chunk_t *error = (sctp_error_chunk_t *)chunk;
                sctp_cmd_seq_add(commands, sctp_cmd_error(error->error_type, error->parameters));
                return SCTP_DISPOSITION_CONSUME;
            }

        default:
            return SCTP_DISPOSITION_UNKNOWN;
    }
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment the appropriate statistics */
    net->sctp.statistics.ctlchunks_rcvd++;

    if (!sctp_chunk_length_valid(arg)) {
        return SCTP_DISPOSITION_BAD;
    }

    switch (type) {
    case SCTP_SUBTYPE_SHUTDOWN_ACK:
        sctp_handle_shutdown_ack(net, ep, asoc, arg, commands);
        break;
    case SCTP_SUBTYPE_COOKIE_ACK:
        sctp_handle_cookie_ack(net, ep, asoc, arg, commands);
        break;
    case SCTP_SUBTYPE_ERROR:
        sctp_handle_error(net, ep, asoc, arg, commands);
        break;
    default:
        disposition = SCTP_DISPOSITION_DISCARD;
        break;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment the appropriate SCTP statistics */
    net->sctp.statistics.out_of_band_chunks++;

    /* Validate the chunk length */
    if (sctp_chunk_length_invalid(arg)) {
        return SCTP_DISPOSITION_ERROR;
    }

    switch (type) {
        case SCTP_SUBTYPE_SHUTDOWN_ACK:
            sctp_handle_shutdown_ack(net, ep, asoc, arg, commands);
            break;

        case SCTP_SUBTYPE_COOKIE_ACK:
            sctp_handle_cookie_ack(net, ep, asoc, arg, commands);
            break;

        case SCTP_SUBTYPE_ERROR:
            sctp_handle_error(net, ep, asoc, arg, commands);
            break;

        default:
            disposition = SCTP_DISPOSITION_IGNORE;
            break;
    }

    return disposition;
}

sctp_disposition_t process_sctp_chunk(struct net *net, const struct sctp_endpoint *ep,
                                      const struct sctp_association *asoc, sctp_subtype_t type,
                                      void *arg, sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment statistics */
    net->sctp.statistics[SCTP_STAT_CHUNK_RECEIVED]++;

    /* Validate chunk length */
    if (!sctp_chunk_length_valid(arg)) {
        disposition = SCTP_DISPOSITION_DROP;
        return disposition;
    }

    switch (type) {
        case SCTP_SUBTYPE_SHUTDOWN_ACK:
            sctp_process_shutdown_ack(net, ep, asoc, arg, commands);
            break;
        case SCTP_SUBTYPE_COOKIE_ACK:
            sctp_process_cookie_ack(net, ep, asoc, arg, commands);
            break;
        case SCTP_SUBTYPE_ERROR:
            sctp_handle_error(net, ep, asoc, arg, commands);
            break;
        default:
            disposition = SCTP_DISPOSITION_IGNORE;
            break;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net, const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc, sctp_subtype_t type,
                                          void *arg, sctp_cmd_seq_t *commands)
{
    struct sctp_chunk *chunk = (struct sctp_chunk *)arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment statistics for processing out-of-band chunk */
    net->sctp.statistics->chunks[type]++;

    /* Validate chunk length */
    if (chunk->length < sizeof(sctp_chunkhdr_t)) {
        disposition = SCTP_DISPOSITION_NOMEM;
        return disposition;
    }

    switch (type) {
    case SCTP_CID_SHUTDOWN_ACK:
        sctp_process_shutdown_ack(net, ep, asoc, chunk, commands);
        break;
    case SCTP_CID_COOKIE_ACK:
        sctp_process_cookie_ack(net, ep, asoc, chunk, commands);
        break;
    case SCTP_CID_ERROR:
        sctp_process_error(net, ep, asoc, chunk, commands);
        break;
    default:
        disposition = SCTP_DISPOSITION_DISCARD;
        break;
    }

    return disposition;
}
